const input = $json;

function clean(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value).trim();
}

const event = {
  event_id: clean(input.event_id),
  procurement_id: clean(input.procurement_id),
  event_type: clean(input.event_type).toLowerCase(),
  event_status: clean(input.event_status).toLowerCase(),
  event_timestamp: clean(input.event_timestamp) || new Date().toISOString(),
  requisition_id: clean(input.requisition_id),
  supplier_name: clean(input.supplier_name),
  department: clean(input.department),
  amount: Number(input.amount || 0),
  currency: clean(input.currency) || 'INR',
  requester_email: clean(input.requester_email),
  approver_email: clean(input.approver_email),
  processed: clean(input.processed).toLowerCase(),
  notes: clean(input.notes)
};

return {
  json: {
    ...event,
    normalized_at: new Date().toISOString(),
    source: 'google_sheets'
  }
};

const data = $json;

// =====================================================
// 1. Get normalized procurement event
// =====================================================

const originalEvent = $('Normalize Procurement Event Data').first().json;


// =====================================================
// 2. Extract AI response text
// =====================================================

let aiText = '';

if (
  Array.isArray(data.output) &&
  data.output[0]?.content &&
  Array.isArray(data.output[0].content)
) {
  const outputText = data.output[0].content.find(
    item => item.type === 'output_text'
  );

  if (outputText?.text) {
    aiText = outputText.text;
  }
}


// =====================================================
// 3. Parse AI JSON response
// =====================================================

let recommendation;

try {
  recommendation = JSON.parse(aiText);
} catch (error) {
  recommendation = {
    action: 'manual_review',
    missing_step_key: null,
    priority: 'high',
    owner_role: null,
    reason: 'The AI response was not valid JSON.',
    requires_human_approval: true
  };
}


// =====================================================
// 4. Validate allowed AI actions
// =====================================================

const allowedActions = [
  'trigger_recovery',
  'complete_workflow',
  'manual_review'
];

if (!allowedActions.includes(recommendation.action)) {
  recommendation = {
    action: 'manual_review',
    missing_step_key: null,
    priority: 'high',
    owner_role: null,
    reason: 'The AI returned an unsupported action.',
    requires_human_approval: true
  };
}


// =====================================================
// 5. Validate missing step against workflow data
// =====================================================

const missingSteps = Array.isArray(data.missing_steps)
  ? data.missing_steps
  : [];

const missingKeys = missingSteps
  .map(step => step.key)
  .filter(Boolean);


// Only validate when missing_steps are actually available
if (
  recommendation.action === 'trigger_recovery' &&
  missingKeys.length > 0 &&
  !missingKeys.includes(recommendation.missing_step_key)
) {
  recommendation = {
    action: 'manual_review',
    missing_step_key: null,
    priority: 'high',
    owner_role: null,
    reason:
      'The recommended missing step was not present in the validated workflow data.',
    requires_human_approval: true
  };
}


// =====================================================
// 6. Clean recommendation object
// =====================================================

const cleanRecommendation = {
  action: recommendation.action,
  missing_step_key: recommendation.missing_step_key || null,
  priority: recommendation.priority || 'medium',
  owner_role: recommendation.owner_role || null,
  reason: recommendation.reason || null,
  requires_human_approval:
    recommendation.requires_human_approval ?? true
};


// =====================================================
// 7. Define supported procurement recovery steps
// =====================================================

const allowedSteps = {
  requisition_created: {
    name: 'Requisition Created',
    owner_role: 'Requester',
    recovery_type: 'requisition_recovery'
  },

  sourcing_completed: {
    name: 'Sourcing Completed',
    owner_role: 'Sourcing Manager',
    recovery_type: 'sourcing_recovery'
  },

  supplier_selected: {
    name: 'Supplier Selected',
    owner_role: 'Procurement Manager',
    recovery_type: 'supplier_selection_recovery'
  },

  contract_created: {
    name: 'Contract Created',
    owner_role: 'Legal Team',
    recovery_type: 'contract_creation_recovery'
  },

  contract_approved: {
    name: 'Contract Approved',
    owner_role: 'Legal Approver',
    recovery_type: 'contract_approval_recovery'
  },

  purchase_order_created: {
    name: 'Purchase Order Created',
    owner_role: 'Procurement Officer',
    recovery_type: 'purchase_order_creation_recovery'
  },

  purchase_order_approved: {
    name: 'Purchase Order Approved',
    owner_role: 'Purchase Approver',
    recovery_type: 'purchase_order_approval_recovery'
  },

  goods_received: {
    name: 'Goods Received',
    owner_role: 'Warehouse Manager',
    recovery_type: 'goods_receipt_recovery'
  },

  invoice_submitted: {
    name: 'Invoice Submitted',
    owner_role: 'Supplier',
    recovery_type: 'invoice_submission_recovery'
  },

  invoice_approved: {
    name: 'Invoice Approved',
    owner_role: 'Finance Approver',
    recovery_type: 'invoice_approval_recovery'
  },

  payment_completed: {
    name: 'Payment Completed',
    owner_role: 'Accounts Payable',
    recovery_type: 'payment_recovery'
  }
};


// =====================================================
// 8. Determine missing workflow step
// =====================================================

const missingStepKey = String(
  cleanRecommendation.missing_step_key ||
  data.first_missing_step?.key ||
  ''
)
  .trim()
  .toLowerCase();


// =====================================================
// 9. Determine recovery route
// =====================================================

let routeStatus = 'no_missing_step';
let recoveryRequired = false;
let recoveryType = null;
let missingStepName = null;
let recoveryOwnerRole = null;
let routeMessage = 'No missing procurement step was provided.';
let manualReviewRequired = false;

if (missingStepKey) {

  const routeDetails = allowedSteps[missingStepKey];

  if (!routeDetails) {

    routeStatus = 'unsupported_step';
    recoveryRequired = false;
    recoveryType = null;
    missingStepName = null;
    recoveryOwnerRole = null;

    routeMessage =
      `Unsupported missing step: ${missingStepKey}`;

    manualReviewRequired = true;

  } else {

    routeStatus = 'valid';
    recoveryRequired = true;

    missingStepName = routeDetails.name;
    recoveryOwnerRole = routeDetails.owner_role;
    recoveryType = routeDetails.recovery_type;

    routeMessage =
      `Recovery workflow selected for ${routeDetails.name}.`;
  }
}


// =====================================================
// 10. Return final combined output
// =====================================================

return {
  json: {

    // ---------------------------------------------
    // Original normalized procurement event
    // ---------------------------------------------
    original_event: originalEvent,

    // ---------------------------------------------
    // AI recommendation
    // ---------------------------------------------
    recommendation: cleanRecommendation,

    // ---------------------------------------------
    // Recovery routing
    // ---------------------------------------------
    route_status: routeStatus,

    recovery_required: recoveryRequired,

    missing_step_key: missingStepKey || null,

    missing_step_name: missingStepName,

    recovery_owner_role: recoveryOwnerRole,

    recovery_type: recoveryType,

    route_message: routeMessage,

    manual_review_required: manualReviewRequired
  }
};

