const event = $('Normalize Procurement Event Data').first().json;

// =====================================================
// 1. Get Workflow State
// =====================================================

const stateItems = $('Retrieve Procurement Workflow State').all();

const state = stateItems.length > 0
  ? stateItems[0].json
  : {};


// =====================================================
// 2. Get Procurement Workflow Steps
// =====================================================

const stepItems = $('Load Required Procurement Lifecycle Steps').all();

const expectedSteps = stepItems
  .map(item => item.json)
  .filter(step =>
    step.step_key &&
    String(step.required || '').trim().toLowerCase() === 'yes'
  )
  .map(step => ({
    order: Number(step.step_order),
    key: String(step.step_key).trim().toLowerCase(),
    name: String(step.step_name || '').trim(),
    owner_role: String(step.owner_role || '').trim(),
    success_event_type: String(
      step.success_event_type || ''
    ).trim().toLowerCase()
  }))
  .filter(step => step.success_event_type)
  .sort((a, b) => a.order - b.order);


// =====================================================
// 3. Parse Completed Steps
// =====================================================

let completedSteps = [];

if (Array.isArray(state.completed_steps)) {

  completedSteps = state.completed_steps;

} else if (typeof state.completed_steps === 'string') {

  completedSteps = state.completed_steps
    .split(',')
    .map(step => String(step).trim().toLowerCase())
    .filter(Boolean);
}


// =====================================================
// 4. Add Current Procurement Event
// =====================================================

const currentEventType = String(
  event.event_type || ''
)
  .trim()
  .toLowerCase();

if (
  currentEventType &&
  !completedSteps.includes(currentEventType)
) {
  completedSteps.push(currentEventType);
}


// Remove duplicates
completedSteps = [...new Set(completedSteps)];


// =====================================================
// 5. Determine Missing Steps
// =====================================================

const completedSet = new Set(completedSteps);

const missingSteps = expectedSteps
  .filter(step =>
    !completedSet.has(step.success_event_type)
  )
  .map(step => ({
    order: step.order,
    key: step.key,
    name: step.name,
    owner_role: step.owner_role,
    success_event_type: step.success_event_type
  }));


// =====================================================
// 6. Determine First Missing Step
// =====================================================

const firstMissingStep =
  missingSteps.length > 0
    ? missingSteps[0]
    : null;


// =====================================================
// 7. Determine Workflow Status
// =====================================================

const hasGap = missingSteps.length > 0;

const workflowStatus = hasGap
  ? 'gap_detected'
  : 'completed';

const reconnectionStatus = hasGap
  ? 'recovery_required'
  : 'not_required';


// =====================================================
// 8. Return Combined Output
// =====================================================

return {
  json: {

    // ---------------------------------------------
    // Original normalized procurement event
    // ---------------------------------------------

    event_id: event.event_id || null,

    procurement_id: event.procurement_id || null,

    event_type: event.event_type || null,

    event_status: event.event_status || null,

    event_timestamp: event.event_timestamp || null,

    requisition_id: event.requisition_id || null,

    supplier_name: event.supplier_name || null,

    department: event.department || null,

    amount: event.amount || null,

    currency: event.currency || null,

    requester_email: event.requester_email || null,

    approver_email: event.approver_email || null,

    processed: event.processed || null,

    notes: event.notes || null,

    normalized_at: event.normalized_at || null,

    source: event.source || null,


    // ---------------------------------------------
    // Workflow state
    // ---------------------------------------------

    state_row_number:
      state.rowNumber ||
      state.row_number ||
      null,

    existing_state: state,


    // ---------------------------------------------
    // Workflow steps
    // ---------------------------------------------

    expected_steps: expectedSteps,

    completed_steps: completedSteps,

    missing_steps: missingSteps,

    first_missing_step: firstMissingStep,


    // ---------------------------------------------
    // Workflow status
    // ---------------------------------------------

    has_gap: hasGap,

    workflow_status: workflowStatus,

    reconnection_status: reconnectionStatus,

    detected_at: new Date().toISOString()
  }
};
